-- Initial UCE foundation. UUID defaults are generated by Prisma Client.

CREATE TYPE "Visibility" AS ENUM ('PRIVATE', 'PUBLIC');

CREATE TYPE "MemberRole" AS ENUM ('EDITOR', 'VIEWER');

CREATE TYPE "ScanStatus" AS ENUM ('PENDING', 'READY', 'REJECTED');

CREATE TYPE "ReviewStatus" AS ENUM ('REQUESTED', 'ACCEPTED', 'COMPLETED', 'DECLINED', 'REVOKED');

CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT', 'OPEN_INTEREST', 'CLOSED');

CREATE TABLE "User" (
  "id" UUID NOT NULL,
  "subject" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Session" (
  "tokenHash" TEXT NOT NULL,
  "userId" UUID NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Session_pkey" PRIMARY KEY ("tokenHash")
);

CREATE TABLE "AuthFlow" (
  "stateHash" TEXT NOT NULL,
  "verifier" TEXT NOT NULL,
  "nonce" TEXT NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "AuthFlow_pkey" PRIMARY KEY ("stateHash")
);

CREATE TABLE "CreatorProfile" (
  "userId" UUID NOT NULL,
  "displayName" TEXT NOT NULL,
  "biography" TEXT NOT NULL DEFAULT '',
  "disciplines" TEXT[] NOT NULL,
  "skills" TEXT[] NOT NULL,
  "languages" TEXT[] NOT NULL,
  "region" TEXT NOT NULL DEFAULT '',
  "links" TEXT[] NOT NULL,
  "visibility" "Visibility" NOT NULL DEFAULT 'PRIVATE',
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "CreatorProfile_pkey" PRIMARY KEY ("userId")
);

CREATE TABLE "Project" (
  "id" UUID NOT NULL,
  "ownerId" UUID NOT NULL,
  "title" TEXT NOT NULL,
  "summary" TEXT NOT NULL DEFAULT '',
  "discipline" TEXT NOT NULL,
  "visibility" "Visibility" NOT NULL DEFAULT 'PRIVATE',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "Project_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ProjectMember" (
  "projectId" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "role" "MemberRole" NOT NULL DEFAULT 'VIEWER',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ProjectMember_pkey" PRIMARY KEY ("projectId", "userId")
);

CREATE TABLE "Work" (
  "id" UUID NOT NULL,
  "projectId" UUID NOT NULL,
  "title" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "claimedAuthor" TEXT NOT NULL,
  "claimedCreatedAt" TIMESTAMP(3),
  "sensitive" BOOLEAN NOT NULL DEFAULT false,
  "culturalNotes" TEXT NOT NULL DEFAULT '',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Work_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "WorkVersion" (
  "id" UUID NOT NULL,
  "workId" UUID NOT NULL,
  "number" INTEGER NOT NULL,
  "content" TEXT NOT NULL,
  "note" TEXT NOT NULL,
  "manifestHash" TEXT NOT NULL,
  "recordedBy" UUID NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "WorkVersion_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Asset" (
  "id" UUID NOT NULL,
  "workId" UUID NOT NULL,
  "filename" TEXT NOT NULL,
  "mimeType" TEXT NOT NULL,
  "size" INTEGER NOT NULL,
  "objectKey" TEXT NOT NULL,
  "objectVersion" TEXT,
  "sha256" TEXT,
  "status" "ScanStatus" NOT NULL DEFAULT 'PENDING',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Asset_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "VersionAsset" (
  "versionId" UUID NOT NULL,
  "assetId" UUID NOT NULL,
  CONSTRAINT "VersionAsset_pkey" PRIMARY KEY ("versionId", "assetId")
);

CREATE TABLE "Contributor" (
  "id" UUID NOT NULL,
  "workId" UUID NOT NULL,
  "name" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "note" TEXT NOT NULL DEFAULT '',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Contributor_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "RightsRecord" (
  "id" UUID NOT NULL,
  "workId" UUID NOT NULL,
  "party" TEXT NOT NULL,
  "rightType" TEXT NOT NULL,
  "territory" TEXT NOT NULL,
  "use" TEXT NOT NULL,
  "startsAt" TIMESTAMP(3) NOT NULL,
  "endsAt" TIMESTAMP(3),
  "shareBasisPoints" INTEGER,
  "agreementAssetId" UUID NOT NULL,
  "note" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "RightsRecord_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Institution" (
  "id" UUID NOT NULL,
  "adminId" UUID NOT NULL,
  "name" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "website" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "verifiedAt" TIMESTAMP(3),
  "verificationReference" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Institution_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ExpertProfile" (
  "userId" UUID NOT NULL,
  "biography" TEXT NOT NULL,
  "qualifications" TEXT NOT NULL,
  "expertise" TEXT[] NOT NULL,
  "languages" TEXT[] NOT NULL,
  "regions" TEXT[] NOT NULL,
  "publications" TEXT[] NOT NULL,
  "available" BOOLEAN NOT NULL DEFAULT true,
  "public" BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT "ExpertProfile_pkey" PRIMARY KEY ("userId")
);

CREATE TABLE "Affiliation" (
  "id" UUID NOT NULL,
  "expertId" UUID NOT NULL,
  "institutionId" UUID NOT NULL,
  "title" TEXT NOT NULL,
  "confirmedAt" TIMESTAMP(3),
  CONSTRAINT "Affiliation_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ReviewRequest" (
  "id" UUID NOT NULL,
  "versionId" UUID NOT NULL,
  "reviewerId" UUID NOT NULL,
  "requestedBy" UUID NOT NULL,
  "question" TEXT NOT NULL,
  "consentNote" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "compensation" TEXT NOT NULL,
  "status" "ReviewStatus" NOT NULL DEFAULT 'REQUESTED',
  "conflictDeclaration" TEXT,
  "affiliationSnapshot" JSONB,
  "reviewerSnapshot" JSONB,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ReviewRequest_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ReviewReport" (
  "id" UUID NOT NULL,
  "requestId" UUID NOT NULL,
  "outcome" TEXT NOT NULL,
  "methodology" TEXT NOT NULL,
  "limitations" TEXT NOT NULL,
  "recommendations" TEXT NOT NULL,
  "sources" JSONB NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ReviewReport_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Campaign" (
  "id" UUID NOT NULL,
  "projectId" UUID NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "targetMinor" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'ZAR',
  "status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Campaign_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Milestone" (
  "id" UUID NOT NULL,
  "campaignId" UUID NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "completedAt" TIMESTAMP(3),
  CONSTRAINT "Milestone_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Pledge" (
  "id" UUID NOT NULL,
  "campaignId" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "amountMinor" INTEGER NOT NULL,
  "kind" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Pledge_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "AiRun" (
  "id" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "projectId" UUID NOT NULL,
  "versionId" UUID NOT NULL,
  "provider" TEXT NOT NULL,
  "endpoint" TEXT NOT NULL,
  "model" TEXT NOT NULL,
  "instruction" TEXT NOT NULL,
  "consentAt" TIMESTAMP(3) NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'PENDING',
  "output" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "AiRun_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Job" (
  "id" UUID NOT NULL,
  "kind" TEXT NOT NULL,
  "resourceId" UUID NOT NULL,
  "state" TEXT NOT NULL DEFAULT 'PENDING',
  "lockedAt" TIMESTAMP(3),
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "error" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Job_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "AuditEvent" (
  "id" UUID NOT NULL,
  "actorId" UUID NOT NULL,
  "action" TEXT NOT NULL,
  "resourceId" UUID NOT NULL,
  "detail" JSONB NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "User_subject_key" ON "User" ("subject");

CREATE INDEX "Session_expiresAt_idx" ON "Session" ("expiresAt");

CREATE INDEX "AuthFlow_expiresAt_idx" ON "AuthFlow" ("expiresAt");

CREATE INDEX "Project_ownerId_createdAt_idx" ON "Project" ("ownerId", "createdAt");

CREATE INDEX "ProjectMember_userId_idx" ON "ProjectMember" ("userId");

CREATE INDEX "Work_projectId_idx" ON "Work" ("projectId");

CREATE UNIQUE INDEX "WorkVersion_workId_number_key" ON "WorkVersion" ("workId", "number");

CREATE UNIQUE INDEX "Asset_objectKey_key" ON "Asset" ("objectKey");

CREATE UNIQUE INDEX "Affiliation_expertId_institutionId_key" ON "Affiliation" ("expertId", "institutionId");

CREATE INDEX "ReviewRequest_reviewerId_status_idx" ON "ReviewRequest" ("reviewerId", "status");

CREATE UNIQUE INDEX "ReviewReport_requestId_key" ON "ReviewReport" ("requestId");

CREATE UNIQUE INDEX "Campaign_projectId_key" ON "Campaign" ("projectId");

CREATE UNIQUE INDEX "Pledge_campaignId_userId_key" ON "Pledge" ("campaignId", "userId");

CREATE INDEX "AiRun_userId_createdAt_idx" ON "AiRun" ("userId", "createdAt");

CREATE UNIQUE INDEX "Job_resourceId_key" ON "Job" ("resourceId");

CREATE INDEX "Job_state_createdAt_idx" ON "Job" ("state", "createdAt");

CREATE INDEX "AuditEvent_resourceId_createdAt_idx" ON "AuditEvent" ("resourceId", "createdAt");

ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "CreatorProfile" ADD CONSTRAINT "CreatorProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Project" ADD CONSTRAINT "Project_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ProjectMember" ADD CONSTRAINT "ProjectMember_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "ProjectMember" ADD CONSTRAINT "ProjectMember_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Work" ADD CONSTRAINT "Work_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "WorkVersion" ADD CONSTRAINT "WorkVersion_workId_fkey" FOREIGN KEY ("workId") REFERENCES "Work" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Asset" ADD CONSTRAINT "Asset_workId_fkey" FOREIGN KEY ("workId") REFERENCES "Work" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "VersionAsset" ADD CONSTRAINT "VersionAsset_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "WorkVersion" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "VersionAsset" ADD CONSTRAINT "VersionAsset_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Contributor" ADD CONSTRAINT "Contributor_workId_fkey" FOREIGN KEY ("workId") REFERENCES "Work" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "RightsRecord" ADD CONSTRAINT "RightsRecord_workId_fkey" FOREIGN KEY ("workId") REFERENCES "Work" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "RightsRecord" ADD CONSTRAINT "RightsRecord_agreementAssetId_fkey" FOREIGN KEY ("agreementAssetId") REFERENCES "Asset" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Institution" ADD CONSTRAINT "Institution_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ExpertProfile" ADD CONSTRAINT "ExpertProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Affiliation" ADD CONSTRAINT "Affiliation_expertId_fkey" FOREIGN KEY ("expertId") REFERENCES "ExpertProfile" ("userId") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Affiliation" ADD CONSTRAINT "Affiliation_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "Institution" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ReviewRequest" ADD CONSTRAINT "ReviewRequest_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "WorkVersion" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ReviewRequest" ADD CONSTRAINT "ReviewRequest_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ReviewReport" ADD CONSTRAINT "ReviewReport_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ReviewRequest" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Campaign" ADD CONSTRAINT "Campaign_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Milestone" ADD CONSTRAINT "Milestone_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Pledge" ADD CONSTRAINT "Pledge_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Pledge" ADD CONSTRAINT "Pledge_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "AiRun" ADD CONSTRAINT "AiRun_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "AiRun" ADD CONSTRAINT "AiRun_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "AiRun" ADD CONSTRAINT "AiRun_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "WorkVersion" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;
